"use strict";(self.webpackChunkgf_site=self.webpackChunkgf_site||[]).push([["1924"],{55226(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"0.4.x(Latest)","banner":null,"badge":true,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"quickSidebar":[{"type":"link","href":"/quick/overview","label":"Overview","docId":"quick/overview","unlisted":false},{"type":"link","href":"/quick/environment","label":"Environment","docId":"quick/environment","unlisted":false},{"type":"link","href":"/quick/installation","label":"Quick Installation","docId":"quick/installation","unlisted":false},{"type":"link","href":"/quick/have-a-try","label":"Have a Try","docId":"quick/have-a-try","unlisted":false}],"docsSidebar":[{"type":"category","label":"Concepts","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/ai-native","label":"AI Native","docId":"docs/concepts/ai-native","unlisted":false},{"type":"link","href":"/docs/modular-design","label":"Modular Design","docId":"docs/concepts/modular-design","unlisted":false},{"type":"link","href":"/docs/spec-driven-development","label":"Spec Driven Development","docId":"docs/concepts/spec-driven-development","unlisted":false},{"type":"link","href":"/docs/ai-engineering-quality","label":"AI Engineering Quality","docId":"docs/concepts/ai-engineering-quality","unlisted":false},{"type":"link","href":"/docs/capability-boundary","label":"Capability Boundaries","docId":"docs/concepts/capability-boundary","unlisted":false}],"href":"/docs/concepts"},{"type":"category","label":"Components","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/core-host","label":"Core Host","docId":"docs/components/core-host","unlisted":false},{"type":"link","href":"/docs/admin-workspace","label":"Admin Workspace","docId":"docs/components/admin-workspace","unlisted":false},{"type":"category","label":"Plugin System","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/source-plugins","label":"Source Plugin Development Guide","docId":"docs/components/plugin-system/source-plugins","unlisted":false},{"type":"link","href":"/docs/wasm-plugins","label":"Dynamic Plugins and WASM Runtime","docId":"docs/components/plugin-system/wasm-plugins","unlisted":false},{"type":"link","href":"/docs/plugin-management","label":"Plugin Installation, Upgrades, and Governance","docId":"docs/components/plugin-system/plugin-management","unlisted":false},{"type":"link","href":"/docs/plugin-config","label":"Plugin Configuration Management","docId":"docs/components/plugin-system/plugin-config","unlisted":false},{"type":"link","href":"/docs/plugin-manifest","label":"Manifest Delivery Resources","docId":"docs/components/plugin-system/plugin-manifest","unlisted":false}],"href":"/docs/plugin-system"},{"type":"link","href":"/docs/distributed-architecture","label":"Distributed Architecture","docId":"docs/components/distributed-architecture","unlisted":false},{"type":"link","href":"/docs/configuration","label":"Configuration","docId":"docs/components/configuration","unlisted":false},{"type":"link","href":"/docs/routing","label":"Routing","docId":"docs/components/routing","unlisted":false},{"type":"link","href":"/docs/permission","label":"Permission","docId":"docs/components/permission","unlisted":false},{"type":"link","href":"/docs/static-assets","label":"Static Assets","docId":"docs/components/static-assets","unlisted":false},{"type":"link","href":"/docs/api-reference","label":"API Reference","docId":"docs/components/api-reference","unlisted":false},{"type":"link","href":"/docs/multi-tenant","label":"Multi Tenant","docId":"docs/components/multi-tenant","unlisted":false},{"type":"link","href":"/docs/cron-tasks","label":"Cron Tasks","docId":"docs/components/cron-tasks","unlisted":false},{"type":"link","href":"/docs/i18n","label":"I18N","docId":"docs/components/i18n","unlisted":false}],"href":"/docs/components"},{"type":"category","label":"Domain Capabilities","collapsible":true,"collapsed":true,"items":[{"type":"category","label":"Declaration Capabilities","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/declaration-assets","label":"Assets","docId":"docs/domain-capabilities/declaration-capabilities/assets","unlisted":false},{"type":"link","href":"/docs/declaration-access","label":"Access","docId":"docs/domain-capabilities/declaration-capabilities/access","unlisted":false},{"type":"link","href":"/docs/declaration-hooks","label":"Hooks","docId":"docs/domain-capabilities/declaration-capabilities/hooks","unlisted":false},{"type":"link","href":"/docs/declaration-jobs","label":"Jobs","docId":"docs/domain-capabilities/declaration-capabilities/jobs","unlisted":false},{"type":"link","href":"/docs/declaration-lifecycle","label":"Lifecycle","docId":"docs/domain-capabilities/declaration-capabilities/lifecycle","unlisted":false},{"type":"link","href":"/docs/declaration-providers","label":"Providers","docId":"docs/domain-capabilities/declaration-capabilities/providers","unlisted":false},{"type":"link","href":"/docs/declaration-routes","label":"Routes","docId":"docs/domain-capabilities/declaration-capabilities/routes","unlisted":false}],"href":"/docs/declaration-capabilities"},{"type":"link","href":"/docs/domain-capability-ai","label":"AI","docId":"docs/domain-capabilities/ai","unlisted":false},{"type":"link","href":"/docs/domain-capability-apidoc","label":"APIDoc","docId":"docs/domain-capabilities/apidoc","unlisted":false},{"type":"link","href":"/docs/domain-capability-auth","label":"Auth","docId":"docs/domain-capabilities/auth","unlisted":false},{"type":"link","href":"/docs/domain-capability-bizctx","label":"BizCtx","docId":"docs/domain-capabilities/bizctx","unlisted":false},{"type":"link","href":"/docs/domain-capability-cache","label":"Cache","docId":"docs/domain-capabilities/cache","unlisted":false},{"type":"link","href":"/docs/domain-capability-dict","label":"Dict","docId":"docs/domain-capabilities/dict","unlisted":false},{"type":"link","href":"/docs/domain-capability-files","label":"Files","docId":"docs/domain-capabilities/files","unlisted":false},{"type":"link","href":"/docs/domain-capability-hostconfig","label":"HostConfig","docId":"docs/domain-capabilities/hostconfig","unlisted":false},{"type":"link","href":"/docs/domain-capability-i18n","label":"I18n","docId":"docs/domain-capabilities/i18n","unlisted":false},{"type":"link","href":"/docs/domain-capability-infra","label":"Infra","docId":"docs/domain-capabilities/infra","unlisted":false},{"type":"link","href":"/docs/domain-capability-jobs","label":"Jobs","docId":"docs/domain-capabilities/jobs","unlisted":false},{"type":"link","href":"/docs/domain-capability-lock","label":"Lock","docId":"docs/domain-capabilities/lock","unlisted":false},{"type":"link","href":"/docs/domain-capability-manifest","label":"Manifest","docId":"docs/domain-capabilities/manifest","unlisted":false},{"type":"link","href":"/docs/domain-capability-network","label":"Network","docId":"docs/domain-capabilities/network","unlisted":false},{"type":"link","href":"/docs/domain-capability-notifications","label":"Notifications","docId":"docs/domain-capabilities/notifications","unlisted":false},{"type":"link","href":"/docs/domain-capability-org","label":"Org","docId":"docs/domain-capabilities/org","unlisted":false},{"type":"link","href":"/docs/domain-capability-plugins","label":"Plugins","docId":"docs/domain-capabilities/plugins","unlisted":false},{"type":"link","href":"/docs/domain-capability-recordstore","label":"RecordStore","docId":"docs/domain-capabilities/recordstore","unlisted":false},{"type":"link","href":"/docs/domain-capability-route","label":"Route","docId":"docs/domain-capabilities/route","unlisted":false},{"type":"link","href":"/docs/domain-capability-runtime","label":"Runtime","docId":"docs/domain-capabilities/runtime","unlisted":false},{"type":"link","href":"/docs/domain-capability-sessions","label":"Sessions","docId":"docs/domain-capabilities/sessions","unlisted":false},{"type":"link","href":"/docs/domain-capability-storage","label":"Storage","docId":"docs/domain-capabilities/storage","unlisted":false},{"type":"link","href":"/docs/domain-capability-tenant","label":"Tenant","docId":"docs/domain-capabilities/tenant","unlisted":false},{"type":"link","href":"/docs/domain-capability-users","label":"Users","docId":"docs/domain-capabilities/users","unlisted":false}],"href":"/docs/domain-capabilities"},{"type":"category","label":"Tools","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/commands","label":"Commands","docId":"docs/tools/commands","unlisted":false},{"type":"link","href":"/docs/agent-skills","label":"Agent Skills","docId":"docs/tools/agent-skills","unlisted":false}],"href":"/docs/tools"}],"communitySidebar":[{"type":"link","href":"/community","label":"Community","docId":"community/community","unlisted":false},{"type":"link","href":"/community/support","label":"Support","docId":"community/support","unlisted":false}]},"docs":{"community/community":{"id":"community/community","title":"Community","description":"Official LinaPro community channels \u2014 QQ groups, WeChat, Discord, and GitHub Issues \u2014 with guidance on which channel is best for real-time discussion, reproducible bugs, feature requests, documentation feedback, and plugin development questions.","sidebar":"communitySidebar"},"community/support":{"id":"community/support","title":"Support","description":"Practical ways to support the long-term maintenance of LinaPro, including filing reproducible issues, improving documentation, sharing production experience, joining community discussions, and donating through WeChat Pay or Alipay. Please include your GitHub or Gitee account name in the donation note so we can keep an accurate donation record.","sidebar":"communitySidebar"},"docs/components/admin-workspace":{"id":"docs/components/admin-workspace","title":"Admin Workspace","description":"the standard frontend consumer of the core framework service and plugin system, covering access control, system settings, job scheduling, multi-tenant management, plugin governance, developer center, and dynamic plugin pages, while maintaining consistency with backend API contracts, menu permissions, and I18N resources.","sidebar":"docsSidebar"},"docs/components/api-reference":{"id":"docs/components/api-reference","title":"API Reference","description":"the core framework, source plugins, and WASM dynamic plugins are unified into a single OpenAPI document through g.Meta contracts, permission tags, API doc i18n resources, the in-workspace developer center debugging page, and third-party tool import.","sidebar":"docsSidebar"},"docs/components/components":{"id":"docs/components/components","title":"Components","description":"a stable foundation paired with on-demand plugin extensibility, explicit contracts replacing implicit coupling, and self-contained composable capabilities. Authentication, RBAC, multi-tenancy, scheduling, i18n, cluster coordination, and API documentation are built into the stable platform foundation; business capabilities are delivered through self-contained component extensions; the frontend and backend are decoupled through public API contracts; components are independently replaceable.","sidebar":"docsSidebar"},"docs/components/configuration":{"id":"docs/components/configuration","title":"Configuration","description":"how config.yaml drives the HTTP server, logging, database, JWT authentication, sessions, monitoring, health probes, scheduling, public admin workspace frontend configuration, internationalization, cluster coordination, file uploads, and plugin governance, with the key configuration boundaries to review before production deployment.","sidebar":"docsSidebar"},"docs/components/core-host":{"id":"docs/components/core-host","title":"Core Host","description":"its responsibility boundaries, runtime request flow, startup and loading sequence, built-in platform capability matrix, plugin extension surfaces, and collaboration with the admin workspace, source plugins, WASM dynamic plugins, PostgreSQL, and Redis. It helps developers build a system-level map before reading deeper pages on configuration, permissions, API documentation, scheduled tasks, internationalization, multi-tenancy, the plugin system, and distributed architecture.","sidebar":"docsSidebar"},"docs/components/cron-tasks":{"id":"docs/components/cron-tasks","title":"Cron Tasks","description":"task types, cron expressions, task groups, execution logs, built-in tasks, source plugin and dynamic plugin task declarations, master_only and all_node execution scopes, singleton and parallel concurrency strategies, and cluster scheduling behavior.","sidebar":"docsSidebar"},"docs/components/distributed-architecture":{"id":"docs/components/distributed-architecture","title":"Distributed Architecture","description":"how to switch between single-node and cluster mode, the Redis coordinator, leader election, node responsibilities, cache revision, distributed locks, key-value cache, scheduled task execution scope, and the horizontal scaling process \u2014 helping developers understand how business code can scale to multi-node deployment with zero modifications.","sidebar":"docsSidebar"},"docs/components/i18n":{"id":"docs/components/i18n","title":"I18N","description":"how core framework language packs, plugin language packs, dynamic plugin language resources, API documentation translations, runtime caching, locale configuration, and frontend language switching work together, and what resource boundaries teams must maintain when adding new languages.","sidebar":"docsSidebar"},"docs/components/multi-tenant":{"id":"docs/components/multi-tenant","title":"Multi Tenant","description":"how the core framework bizctx, TenantFilterService, tenant_id filtering interface, default platform tenant, official multi-tenant source plugin, tenant impersonation, plugin multi-tenant manifest fields, and the current Pool shared-database model work together.","sidebar":"docsSidebar"},"docs/components/permission":{"id":"docs/components/permission","title":"Permission","description":"permission management strategy of the LinaPro core framework service, including the issuance, parsing, and revocation of dual JWTs (Access Token and Refresh Token), lifecycle management of both token types, online session management via hot-state storage, the design of the RBAC role-permission model (three-tier relationship: role \u2192 menu \u2192 permission), token-scoped access context caching with revision-based invalidation, declarative API permission management via g.Meta struct tags and the Permission middleware enforcement flow, and menu permission management (menu types, role-menu associations, permission trees, and data scope control) \u2014 giving developers a complete understanding of the authentication and authorization system.","sidebar":"docsSidebar"},"docs/components/plugin-system/plugin-config":{"id":"docs/components/plugin-system/plugin-config","title":"Plugin Configuration Management","description":"How source and dynamic plugins use independent configuration files, how development-time default configuration is maintained, how production environments override plugin configuration, how dynamic plugin artifacts carry default configuration, and how to read plugin and host configuration in code. Helps developers implement per-plugin runtime parameters without modifying the core framework configuration.","sidebar":"docsSidebar"},"docs/components/plugin-system/plugin-management":{"id":"docs/components/plugin-system/plugin-management","title":"Plugin Installation, Upgrades, and Governance","description":"Covers plugin source configuration, the local plugin workspace, plugins.init, plugins.install, plugins.update, plugins.status, admin-side installation and enablement, disablement and uninstallation, dynamic plugin upload, and the full runtime upgrade pipeline to help developers understand the governance process from code acquisition to runtime activation.","sidebar":"docsSidebar"},"docs/components/plugin-system/plugin-manifest":{"id":"docs/components/plugin-system/plugin-manifest","title":"Manifest Delivery Resources","description":"Covers the directory structure of plugin Manifest delivery resources, the source plugin embed compilation process, the dynamic plugin artifact packaging mechanism, the Manifest resource reading interface, dynamic plugin resource authorization, path safety constraints, and design benefits. Helps developers understand how plugin versions carry and manage SQL, i18n, frontend pages, and custom resource files.","sidebar":"docsSidebar"},"docs/components/plugin-system/plugin-system":{"id":"docs/components/plugin-system/plugin-system","title":"Plugin System","description":"Why source plugins and WASM dynamic plugins share a single governance pipeline, and how plugin ID conventions, catalog, dependency, lifecycle, integration, plugin-runtime cache, pluginhost, pluginbridge, plugin.yaml, multi-tenant fields, lifecycle states, isolation mechanisms, and runtime upgrades together form an extensible plugin system.","sidebar":"docsSidebar"},"docs/components/plugin-system/source-plugins":{"id":"docs/components/plugin-system/source-plugins","title":"Source Plugin Development Guide","description":"Covers use cases, directory structure, plugin.yaml manifest, plugin ID naming conventions, installation SQL, API contracts, service layer implementation, pluginhost registration, database access, frontend pages, event hooks, runtime upgrades, and best practices for extending long-lived business capabilities with native Go.","sidebar":"docsSidebar"},"docs/components/plugin-system/wasm-plugins":{"id":"docs/components/plugin-system/wasm-plugins","title":"Dynamic Plugins and WASM Runtime","description":"Covers WebAssembly (WASM) core concepts and advantages including cross-platform portability, security sandboxing, near-native performance, hot-reloading, and multi-language support. Explains LinaPro WASM dynamic plugin use cases, the sandbox model, pluginbridge protocol, exported functions, hostServices authorization, build process, runtime installation and enablement, explicit upgrades, and key differences from source plugins.","sidebar":"docsSidebar"},"docs/components/routing":{"id":"docs/components/routing","title":"Routing","description":"routing management strategy of the LinaPro core framework service, including the /api/v1 prefix for core framework control-plane APIs, the unified /x/{plugin-id}/... plugin API namespace, the built-in middleware pipeline, layered protected-route design, inline API attribute management via g.Meta struct tags, and the different integration approaches for source-plugin custom non-reserved routes and dynamic-plugin route contracts.","sidebar":"docsSidebar"},"docs/components/static-assets":{"id":"docs/components/static-assets","title":"Static Assets","description":"how the core framework packages runtime resources and admin workspace build output with Go Embed, how plugins explicitly publish public static resources through public_assets, and how the /admin workspace entry, /x plugin API namespace, /x-assets public plugin asset namespace, source-plugin custom routes, and dynamic-plugin frontend resources stay separated. It helps developers design plugin pages, public assets, and cache/version policies correctly.","sidebar":"docsSidebar"},"docs/concepts/ai-engineering-quality":{"id":"docs/concepts/ai-engineering-quality","title":"AI Engineering Quality","description":"the engineering management challenges that arise when AI is introduced into software development, and how LinaPro builds a complete AI engineering quality assurance system through the SDD spec-driven workflow, two layers of project specifications, interface abstraction and anti-leakage API contracts, and high-density test coverage where test code accounts for 39% of the total codebase.","sidebar":"docsSidebar"},"docs/concepts/ai-native":{"id":"docs/concepts/ai-native","title":"AI Native","description":"what AI-native truly means, how it differs from AI-assisted development, how AI participates in every stage of the development lifecycle, the built-in AI skill system covering backend, frontend, testing, performance auditing, and version management, progressive project specification management, and why spec-driven development prevents architectural drift over time.","sidebar":"docsSidebar"},"docs/concepts/capability-boundary":{"id":"docs/concepts/capability-boundary","title":"Capability Boundaries","description":"Defines the responsibility boundaries between the default admin workspace, the core control-plane API, the unified plugin API namespace, plugin public asset hosting, and source plugin HTTP routes. Explains how APIPrefix, route contract, public_assets, source, mount, index, and other conventions apply to both source and dynamic plugins.","sidebar":"docsSidebar"},"docs/concepts/concepts":{"id":"docs/concepts/concepts","title":"Concepts","description":"AI-native design, modular architecture, AI spec-driven development, AI engineering quality assurance, and framework-plugin capability boundaries, helping developers build the right mental model before going deeper into the framework.","sidebar":"docsSidebar"},"docs/concepts/modular-design":{"id":"docs/concepts/modular-design","title":"Modular Design","description":"how the leanness principle (keep the core minimal, extend through plugins), domain-bounded built-in capabilities, a first-class plugin system, stable extension interfaces, and real-world examples like cloud storage and LDAP/OIDC authentication let developers assemble systems from proven building blocks rather than building everything from scratch.","sidebar":"docsSidebar"},"docs/concepts/spec-driven-development":{"id":"docs/concepts/spec-driven-development","title":"Spec Driven Development","description":"the five-stage development loop (explore, propose, implement, review, archive), the responsibilities of AI and humans at each stage, the OpenSpec directory structure and spec file formats, and how spec anchors and mandatory E2E tests prevent architectural drift.","sidebar":"docsSidebar"},"docs/domain-capabilities/ai":{"id":"docs/domain-capabilities/ai","title":"AI","description":"The `AI` capability provides managed text, image, embedding, audio, vision, document, safety, and video sub-capabilities to plugins through `services.AI()` and dynamic `hostServices.ai`. The host handles provider discovery, plugin source injection, method-level authorization, usage attribution, and safe degradation. `purpose` and `tier` are passed at call time via request DTOs, not declared in the plugin manifest.","sidebar":"docsSidebar"},"docs/domain-capabilities/apidoc":{"id":"docs/domain-capabilities/apidoc","title":"APIDoc","description":"The `APIDocService` normalizes static routes, source plugin routes, and dynamic plugin routes into stable operation keys, then resolves them into localized module labels and operation summaries. Source plugins access it through `services.APIDoc()`, while dynamic plugins declare `service: apidoc` in `plugin.yaml` and access it through the `pluginbridge.Default().APIDoc()` client. This capability primarily serves audit logs, operation records, and route semantic display, and does not generate `OpenAPI` documents.","sidebar":"docsSidebar"},"docs/domain-capabilities/auth":{"id":"docs/domain-capabilities/auth","title":"Auth","description":"`Auth()` is the plugin-visible authentication and authorization namespace, aggregating tenant token handoff, tenant switching, impersonation tokens, and authorization reading capabilities. Source plugins access it through `services.Auth()`, while dynamic plugins declare `service: auth` in `plugin.yaml` and access it through the `pluginbridge.Default().Auth()` client. Plugins use this capability to call host token issuance and revocation while avoiding direct contact with `JWT` signing, session storage, role tables, and permission tables.","sidebar":"docsSidebar"},"docs/domain-capabilities/bizctx":{"id":"docs/domain-capabilities/bizctx","title":"BizCtx","description":"The `BizCtxService` transforms user, tenant, impersonation, tenant perspective, and platform bypass state from the host request context into a plugin-visible read-only `CurrentContext`. Source plugins access it through `services.BizCtx()`, while dynamic plugins declare `service: bizctx` in `plugin.yaml` and access it through the `pluginbridge.Default().BizCtx()` client.","sidebar":"docsSidebar"},"docs/domain-capabilities/cache":{"id":"docs/domain-capabilities/cache","title":"Cache","description":"The `CacheService` provides plugin-scoped runtime caching for source plugins and dynamic plugins, supporting string values, integer values, deletion, increment, and expiration policy updates. The host is responsible for binding plugin identity and tenant scope. Cache should only be used as volatile acceleration data and must not serve as the authoritative source for permissions, configuration, plugin state, or business records.","sidebar":"docsSidebar"},"docs/domain-capabilities/declaration-capabilities/access":{"id":"docs/domain-capabilities/declaration-capabilities/access","title":"Access","description":"Access declarations cover the Access() registration interface for source plugins, supporting menu filter and permission filter callback registration. They provide supplementary plugin-side control over workbench navigation and permission validity after the host governance catalog is built. Menus and permissions still have their base declarations from plugin.yaml or host-managed data; AccessDeclarations only carries filter callbacks that source plugins need for dynamic decision-making.","sidebar":"docsSidebar"},"docs/domain-capabilities/declaration-capabilities/assets":{"id":"docs/domain-capabilities/declaration-capabilities/assets","title":"Assets","description":"Assets() is the asset declaration entry point for source plugins. It binds the plugin\'s embedded filesystem via UseEmbeddedFiles(), including manifest files, frontend pages, SQL migration scripts, and i18n resources. This page describes the embedded filesystem directory structure, binding method, and differences in resource management between the two plugin types.","sidebar":"docsSidebar"},"docs/domain-capabilities/declaration-capabilities/declaration-capabilities":{"id":"docs/domain-capabilities/declaration-capabilities/declaration-capabilities","title":"Declaration Capabilities","description":"Declaration capabilities represent the static registration and discovery phase before business logic executes. The host framework builds governance state from declaration output. Source plugins register at compile time via pluginhost.Declarations, while dynamic plugins declare through plugin.yaml manifests and pluginbridge.Declarations. This page provides an overview of the declaration vs. runtime distinction, the declaration mechanisms for both plugin types, and a directory of all declaration capabilities.","sidebar":"docsSidebar"},"docs/domain-capabilities/declaration-capabilities/hooks":{"id":"docs/domain-capabilities/declaration-capabilities/hooks","title":"Hooks","description":"Hook declarations cover the Hooks() registration interface for source plugins and the backend/hooks/*.yaml declaration files for dynamic plugins, supporting subscription to host framework extension point events including authentication events, plugin lifecycle events, and system startup events. This page describes extension point categories, execution modes, hook payloads, source plugin registration methods, and the embedding mechanism for dynamic plugin hook contracts.","sidebar":"docsSidebar"},"docs/domain-capabilities/declaration-capabilities/jobs":{"id":"docs/domain-capabilities/declaration-capabilities/jobs","title":"Jobs","description":"Job declarations cover the Jobs() registration interface for source plugins and the JobContract for dynamic plugins, supporting declaration, registration, and scheduling configuration for scheduled jobs. This page describes the job registration model, job contract fields, execution modes, and registration methods for both plugin types.","sidebar":"docsSidebar"},"docs/domain-capabilities/declaration-capabilities/lifecycle":{"id":"docs/domain-capabilities/declaration-capabilities/lifecycle","title":"Lifecycle","description":"Lifecycle declarations cover the Lifecycle() registration interface for source plugins and the LifecycleContract for dynamic plugins, supporting 16 lifecycle callbacks including install, upgrade, disable, uninstall, tenant disable, tenant delete, and install mode change. This page describes lifecycle hook categories, callback types, input parameters, and registration methods for both plugin types.","sidebar":"docsSidebar"},"docs/domain-capabilities/declaration-capabilities/providers":{"id":"docs/domain-capabilities/declaration-capabilities/providers","title":"Providers","description":"Provider declarations cover the Providers() registration interface for source plugins, supporting registration of SPI capability provider factories including Tenant, Org, and AI providers. This page describes the SPI architecture design, provider factory registration, ProviderEnv injection, and provider status checks.","sidebar":"docsSidebar"},"docs/domain-capabilities/declaration-capabilities/routes":{"id":"docs/domain-capabilities/declaration-capabilities/routes","title":"Routes","description":"Route declarations cover the HTTP() registration interface for source plugins and the Routes() declaration entry for dynamic plugins, supporting HTTP route contribution, route group binding, middleware chain configuration, and global middleware registration. This page describes the route registration model, middleware system, route binding format, and registration methods for both plugin types.","sidebar":"docsSidebar"},"docs/domain-capabilities/dict":{"id":"docs/domain-capabilities/dict","title":"Dict","description":"`Dict()` provides dictionary value label resolution for source plugins and dynamic plugins, helping plugins convert host-managed enum values, status values, and option values into stable label views. Source plugins access it through `services.Dict()`, while dynamic plugins declare `service: dict` in `plugin.yaml` and access it through the `pluginbridge.Default().Dict()` client. Trusted source plugins can refresh views for specific dictionary types through `Admin().Dict().Refresh`.","sidebar":"docsSidebar"},"docs/domain-capabilities/domain-capabilities":{"id":"docs/domain-capabilities/domain-capabilities","title":"Domain Capabilities","description":"Overview of the domain capability model available to plugins, covering the `pkg/plugin` contract boundary, the `pluginhost.Services` catalog for source plugins, the `AdminServices` management commands for trusted source plugins, the `hostServices` authorization catalog for dynamic plugins, and domain capabilities such as Users, Dict, Files, Record Store, Jobs, Runtime, Network, Lock, Notifications, and Plugin Governance. Explains the SPI architecture for optional framework capabilities like AI, Org, and Tenant, including deferred construction, safe degradation, and plugin integration.","sidebar":"docsSidebar"},"docs/domain-capabilities/files":{"id":"docs/domain-capabilities/files","title":"Files","description":"The Files capability is the managed entry point for source plugins and dynamic plugins to read the host file management system. The host manages the full lifecycle of user-uploaded files through the `sys_file` table. Plugins obtain read-only file views through `services.Files()` and perform controlled deletion through `Admin().Files()`. The capability does not expose physical storage paths, file hashes, or underlying storage backends to plugins, providing only `FileProjection` as a safe domain view.","sidebar":"docsSidebar"},"docs/domain-capabilities/hostconfig":{"id":"docs/domain-capabilities/hostconfig","title":"HostConfig","description":"Configuration management in the plugin system spans three domains: plugin self-configuration via `Plugins().Config()`, host configuration reading via `HostConfig()`, and managed runtime configuration via `Admin().HostConfig()`. Dynamic plugins declare their read scope through `plugins.config.get` and `hostconfig.get` respectively. This page explains the relationship between these configuration capabilities so plugin authors can choose the correct entry point.","sidebar":"docsSidebar"},"docs/domain-capabilities/i18n":{"id":"docs/domain-capabilities/i18n","title":"I18n","description":"`I18nService` provides runtime language and translation query capabilities for source plugins. Plugins can read the current request language, return localized text by translation key, and search translation keys by prefix. Dynamic plugins do not publish a standalone `i18n` host service; multilingual resources are delivered through `manifest/i18n` and then unified discovery, merging, caching, and distribution are handled by the host. Dynamic plugin backends should return stable message keys, parameters, and fallback text.","sidebar":"docsSidebar"},"docs/domain-capabilities/infra":{"id":"docs/domain-capabilities/infra","title":"Infra","description":"`Infra()` is a general domain capability for plugins to access host infrastructure component status. Source plugins read component status through `services.Infra()`, while dynamic plugins read the same read-only status view through the `service: infra` host service and `pluginbridge.Default().Infra()`. Trusted source plugins can also trigger component status refresh through `Admin().Infra().RefreshStatus`. This capability only expresses component availability and status labels; it does not carry dynamic plugin logs, plugin state, time, UUID, or node identity reads.","sidebar":"docsSidebar"},"docs/domain-capabilities/jobs":{"id":"docs/domain-capabilities/jobs","title":"Jobs","description":"The Jobs capability covers the `Jobs()` scheduled task view for source plugins, the `Admin().Jobs()` execution and status management commands for trusted source plugins, the `JobsRegistrar` interface layer during source plugin registration, and the `jobs.register` host service for dynamic plugins. This page describes the boundaries between read, management, and registration entry points within the task domain.","sidebar":"docsSidebar"},"docs/domain-capabilities/lock":{"id":"docs/domain-capabilities/lock","title":"Lock","description":"The `Lock` capability provides a managed distributed lock entry point for source plugins and dynamic plugins, supporting lock acquisition, renewal, and release. Source plugins use it directly through `services.Lock()`; dynamic plugins declare lock resource references through `hostServices.lock` and use host-issued `tickets` for renewal and release at runtime.","sidebar":"docsSidebar"},"docs/domain-capabilities/manifest":{"id":"docs/domain-capabilities/manifest","title":"Manifest","description":"`ManifestService` provides read-only access to raw resources under the current plugin\'s `manifest/` directory, supporting byte reads, existence checks, and YAML resource scanning. Source plugins consume it through `services.Manifest()`; dynamic plugins consume it after declaring authorized paths through `hostServices.manifest`.","sidebar":"docsSidebar"},"docs/domain-capabilities/network":{"id":"docs/domain-capabilities/network","title":"Network","description":"The `Network` capability is the entry point for dynamic plugins to make managed outbound HTTP requests through `hostServices.network`. Plugins must declare allowed target URL patterns in `plugin.yaml`; the host handles target address authorization, request execution, and audit policies. Source plugins currently have no standard `Services.Network()` entry point.","sidebar":"docsSidebar"},"docs/domain-capabilities/notifications":{"id":"docs/domain-capabilities/notifications","title":"Notifications","description":"The notifications capability in the latest source code is split into the standard `Notifications()` view read capability, trusted source plugin `Admin().Notifications()` management commands, and the dynamic plugin `notifications` host service. This page explains the entry point differences for notification sending, deletion, and view reading, to help plugins move away from the legacy root-level `services.Notify()` usage.","sidebar":"docsSidebar"},"docs/domain-capabilities/org":{"id":"docs/domain-capabilities/org","title":"Org","description":"`Org()` is an optional framework capability that provides plugins with read-only views of organizational data such as departments, positions, and capability status. The actual organization logic is implemented by a provider plugin; the host is responsible for lazy construction, provider status checks, and graceful degradation. Dynamic plugins can invoke published org view methods through `hostServices.org`.","sidebar":"docsSidebar"},"docs/domain-capabilities/plugins":{"id":"docs/domain-capabilities/plugins","title":"Plugins","description":"`Plugins()` is the plugin governance domain capability namespace, aggregating plugin registry views, plugin local configuration, plugin enable state, capability provider status, and tenant-level lifecycle orchestration. This capability lets source plugins read plugin governance state and handle plugin configuration from a single domain entry point, while providing pre-checks and post-notifications for governance operations such as tenant-level plugin disabling and tenant deletion.","sidebar":"docsSidebar"},"docs/domain-capabilities/recordstore":{"id":"docs/domain-capabilities/recordstore","title":"RecordStore","description":"RecordStore is the governed entry point for dynamic plugins to access their own tables through `hostServices.data` and `pluginbridge.Default().RecordStore()`, covering single-table queries, key-based reads, creation, updates, deletion, and structured transactions. Source plugins do not have a standard `Services.Data()` entry; they typically access plugin-owned tables through the host `dao` package and use `TenantFilter()` when tenant isolation is needed.","sidebar":"docsSidebar"},"docs/domain-capabilities/route":{"id":"docs/domain-capabilities/route","title":"Route","description":"`RouteService` provides a dynamic route metadata view attached to the current request. Source plugins access it through `services.Route()`, while dynamic plugins declare `service: route` in `plugin.yaml` and access it via `pluginbridge.Default().Route()`. It only reads `DynamicRouteMetadata` written by the `pluginbridge` runtime and is not responsible for registering, modifying, or dispatching routes.","sidebar":"docsSidebar"},"docs/domain-capabilities/runtime":{"id":"docs/domain-capabilities/runtime","title":"Runtime","description":"`Runtime()` is a runtime host service client exclusive to dynamic plugins, corresponding to the `service: runtime` declaration in `plugin.yaml`. It provides WASM guests with structured log writing, plugin-scoped state read/write, host time reading, UUID generation, and node identity reading. This capability does not belong to the `capability.Services` standard domain directory; source plugins should use native host logging, context, and injected domain services. Infrastructure component state reads use the separate `Infra()` and `service: infra` capability.","sidebar":"docsSidebar"},"docs/domain-capabilities/sessions":{"id":"docs/domain-capabilities/sessions","title":"Sessions","description":"`Sessions()` provides online session search and batch-read views for source plugins and dynamic plugins. Source plugins access it through `services.Sessions()`, while dynamic plugins declare `service: sessions` in `plugin.yaml` and access it via `pluginbridge.Default().Sessions()`. Trusted source plugins can revoke sessions through `Admin().Sessions().RevokeSession`.","sidebar":"docsSidebar"},"docs/domain-capabilities/storage":{"id":"docs/domain-capabilities/storage","title":"Storage","description":"The Storage capability provides source plugins and dynamic plugins with a plugin-scoped object storage sandbox, supporting object read/write, listing, deletion, and metadata queries. The host ensures security through path authorization and plugin isolation. A built-in local disk provider is included, and custom storage backends can be registered through the Provider interface. Multipart upload is supported for large objects, and authorized paths are automatically cleaned up when a plugin is uninstalled.","sidebar":"docsSidebar"},"docs/domain-capabilities/tenant":{"id":"docs/domain-capabilities/tenant","title":"Tenant","description":"`Tenant()` is an optional framework tenant capability that provides plugins with the current tenant, platform bypass, tenant visibility, user-tenant membership, and tenant switch validation. Source plugins can also append `tenant_id` filters to plugin-owned tables through `pluginhost.Services.TenantFilter()`. The actual multi-tenant strategy is implemented by a provider plugin; the host is responsible for request context degradation, provider status checks, source plugin query filtering, and dynamic `hostServices.tenant` bridging.","sidebar":"docsSidebar"},"docs/domain-capabilities/users":{"id":"docs/domain-capabilities/users","title":"Users","description":"`Users()` provides source plugins and dynamic plugins with protected read access to the user domain, including batch-reading user views, searching visible user candidates, and validating target user visibility. Trusted source plugins can execute user status management commands through `Admin().Users()`. Dynamic plugins declare `service: users` in `plugin.yaml` and access it via `pluginbridge.Default().Users()`.","sidebar":"docsSidebar"},"docs/tools/agent-skills":{"id":"docs/tools/agent-skills","title":"Agent Skills","description":"the optional externally installed OpenSpec CLI, goframe-v2, and find-skills tools or skills, plus project-bundled skills for frontend design, Git workflows, code review, E2E testing, performance auditing, OpenSpec implementation and archiving, and other workflows that load automatically in the project. It also notes that source plugin upgrade scenarios may depend on the lina-upgrade skill provided by the AI tool environment, helping developers understand what each skill does, how to install it, and how to invoke it.","sidebar":"docsSidebar"},"docs/tools/commands":{"id":"docs/tools/commands","title":"Commands","description":"including linactl, the Makefile compatibility entry, the Windows make.cmd wrapper, local environment checks and setup, development server management, full builds, WASM plugin builds, Docker image builds, plugin workspace management, agent resource symlink management, test validation, i18n checks, database initialization, and release governance. It helps developers use the same project toolchain consistently on macOS, Linux, and Windows.","sidebar":"docsSidebar"},"docs/tools/tools":{"id":"docs/tools/tools","title":"Tools","description":"covering every make command with usage examples, and the full AI skills library for frontend design, code review, testing, performance auditing, and OpenSpec workflows.","sidebar":"docsSidebar"},"quick/environment":{"id":"quick/environment","title":"Environment","description":"every dependency required to run LinaPro from source, including Git, Go (1.25+), Node.js (20.19+), pnpm (10.0+), PostgreSQL 14+, the cross-platform linactl development command entry, and the recommended AI-native workflow tools and skills such as Claude Code, OpenSpec CLI, goframe-v2, and find-skills. It also provides installation guidance for macOS, Linux, and Windows so developers can prepare a local development environment before installing LinaPro.","sidebar":"quickSidebar"},"quick/have-a-try":{"id":"quick/have-a-try","title":"Have a Try","description":"requirement exploration with the spec-driven workflow, OpenSpec proposal generation, AI-led code implementation, service startup and feature verification, feedback-driven fixes, and change archival, helping developers understand how LinaPro turns AI Coding tools into a full-cycle delivery process for real business features.","sidebar":"quickSidebar"},"quick/installation":{"id":"quick/installation","title":"Quick Installation","description":"How to install and configure the LinaPro framework in minutes, including cloning the repository via Git, initializing official plugin submodules as needed, preparing a default PostgreSQL database, copying and adjusting configuration files, initializing the database with cross-platform linactl or compatible make commands, loading demo data, starting the development server, and verifying the installation.","sidebar":"quickSidebar"},"quick/overview":{"id":"quick/overview","title":"Overview","description":"LinaPro is an AI-native full-stack framework built on Go + Vue 3 with PostgreSQL by default (optional SQLite), native multi-tenant support, an official plugin submodule, Redis cluster coordination, a dual-mode plugin system, RBAC permission management, scheduled task scheduling, live API documentation, the optional-but-recommended OpenSpec spec-driven AI development workflow, and a lifecycle-spanning AI skill set for building sustainable, continuously deliverable business systems.","sidebar":"quickSidebar"}}}}')}}]);